import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.x7b91k6X.js";const u=JSON.parse('{"title":"漫画 · 第 8 话 构建部署：签名与 CI/CD","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.08-build-deployment.md","filePath":"comics/EP.08-build-deployment.md","lastUpdated":1792677465000}'),l={name:"comics/EP.08-build-deployment.md"};function r(n,e,d,s,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-8-话-构建部署-签名与-ci-cd" tabindex="-1">漫画 · 第 8 话 构建部署：签名与 CI/CD <a class="header-anchor" href="#漫画-·-第-8-话-构建部署-签名与-ci-cd" aria-label="Permalink to &quot;漫画 · 第 8 话 构建部署：签名与 CI/CD&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../08-build-deployment">08-build-deployment.md</a> ｜ 原画：<a href="./EP.08-build-deployment.svg">EP.08-build-deployment.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：发版前夜证书过期、描述文件不匹配，全公司等她重签。</li><li><strong>Runtime 长老</strong>：教她用 fastlane 把签名、打包、上架全自动化。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>iOS 签名体系是新手最大的坎：证书（Certificate）证明你是谁，描述文件（Provisioning Profile）授权哪些设备和能力，Entitlements 声明具体权限。手动管理在多人协作时必然混乱——证书过期、私钥丢失、描述文件不匹配。解法是用 fastlane 的 <code>match</code> 加密存储证书到私有 Git 仓库，<code>gym</code> 打包，<code>pilot</code> 上传 TestFlight，配合 CI/CD 流水线实现全链路无人值守。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>No matching provisioning profile found</code>、<code>Certificate has expired</code>——这两类错误在手动管理签名时太常见。发版前夜证书过期，团队所有人停手等重签；换了新电脑，私钥没导出，编不过。<strong>签名不是玄学，但手动管理必然翻车</strong>。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>签名体系三件套：</p><ul><li><strong>证书（Certificate）</strong>：基于 Apple 颁发的 CSR 生成，证明开发者/团队身份。分为 Development（调试）和 Distribution（发布）。</li><li><strong>描述文件（Provisioning Profile）</strong>：把证书、App ID、设备列表、Entitlements 打包在一起，告诉系统「这个 App 可以在这些设备上用这些权限运行」。</li><li><strong>Entitlements</strong>：声明 App 需要的能力（推送、iCloud、App Group 等），必须与描述文件中的一致。</li></ul><p>fastlane 三件套：</p><ul><li><strong>match</strong>：把证书和描述文件加密存到私有 Git 仓库，所有开发者/CI 机器一键同步，告别「私钥在谁电脑上」的混乱。</li><li><strong>gym</strong>：封装 <code>xcodebuild archive</code>，自动处理签名、导出 ipa。</li><li><strong>pilot</strong>：上传 ipa 到 TestFlight / App Store Connect。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>CI/CD 流水线四步：</p><ol><li><strong>PR 阶段</strong>：SwiftLint 检查风格 + 单元测试全量通过，不通过不能合并；</li><li><strong>合并 main</strong>：触发 archive，<code>fastlane match</code> 拉证书，<code>gym</code> 出 ipa；</li><li><strong>发布 TestFlight</strong>：<code>pilot</code> 上传，自动分发给内部测试组；</li><li><strong>App Store 发布</strong>：审核通过后一键提交。</li></ol><p>配置分离用 <code>.xcconfig</code> 文件，Debug/Release/Enterprise 各一套，不污染 <code>project.pbxproj</code>。</p><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>签名三件套：证书证明身份、描述文件授权、Entitlements 声明权限。</li><li>用 fastlane match 加密存证书，换机器/换人不再卡签名。</li><li>CI/CD 流水线：lint→test→archive→上传，全链路无人值守。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 iOS App 必须签名？不签名会怎样？</p><p><strong>答</strong>：签名是 Apple 平台的安全基石，目的有二：①防止篡改——App 签名后，任何对二进制的修改都会导致签名校验失败，系统拒绝运行；②身份溯源——证书绑定开发者账号，出了安全问题 Apple 能追溯到责任主体。不签名的 App 无法安装到真机（模拟器不需要签名），也无法上架 App Store。企业内部分发用企业证书，同样需要签名。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>查看 <code>examples/fastlane/</code> 下的 Fastfile / Matchfile / Gymfile，理解 fastlane 配置；阅读第 8 章关于 <code>xcodebuild archive -exportArchive</code> 的完整命令和 <code>.xcconfig</code> 写法。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>流水线跑通了，可团队代码风格五花八门、PR review 走过场。第 9 话《团队协作：规范与 Code Review》，建一套让代码质量不掉线的协作规范。</p>',27)])])}const m=t(l,[["render",r]]);export{u as __pageData,m as default};
